import pytest

from seed.types.redirect import Redirect


def test_from_xml_to_xml_round_trips() -> None:
    parsed = Redirect.from_xml('<Redirect method="method">text</Redirect>')
    assert parsed.url == "text"
    assert parsed.method == "method"
    serialized = parsed.to_xml(xml_declaration=False)
    assert ">text<" in serialized
    assert 'method="method"' in serialized
    assert Redirect.from_xml(serialized).to_xml(xml_declaration=False) == serialized
    assert parsed.to_xml().startswith('<?xml version="1.0"')
    assert str(parsed) == parsed.to_xml()


def test_from_xml_preserves_unknown_attributes_and_children() -> None:
    parsed = Redirect.from_xml('<Redirect method="method" dataUnknown="1">text<Unknown a="1">v</Unknown></Redirect>')
    serialized = parsed.to_xml(xml_declaration=False)
    assert 'dataUnknown="1"' in serialized
    assert '<Unknown a="1">v</Unknown>' in serialized
    assert Redirect.from_xml(serialized).to_xml(xml_declaration=False) == serialized


def test_to_xml_escapes_special_characters() -> None:
    model = Redirect(url="a & b < c > d \"q\" 'r'", method="method")
    serialized = model.to_xml(xml_declaration=False)
    assert "a & b" not in serialized
    assert "< c" not in serialized
    assert Redirect.from_xml(serialized).url == "a & b < c > d \"q\" 'r'"


def test_from_xml_rejects_wrong_root_element() -> None:
    with pytest.raises(ValueError):
        Redirect.from_xml("<NotTheRedirect />")


def test_from_xml_rejects_malformed_xml() -> None:
    with pytest.raises(ValueError):
        Redirect.from_xml("<Redirect><unclosed>")


def test_from_xml_rejects_doctype() -> None:
    with pytest.raises(ValueError):
        Redirect.from_xml('<!DOCTYPE Redirect [<!ENTITY xxe "injected">]><Redirect>&xxe;</Redirect>')
